/* YoroOS 0.2.4 - Crisp Supersampled Anti-Aliased Minimalist Icon Renderer
 *
 * Uses 10.67x Lanczos-supersampled RGBA sprites (g_icon48_bgra & g_icon28_bgra)
 * generated by tools/mkassets.py + clean flat minimal utility symbols.
 * ZERO Windows 4-square logos anywhere in the OS.
 */
#include "kernel.h"

extern const u32 g_icon48_bgra[19][48 * 48];
extern const u32 g_icon28_bgra[19][28 * 28];

enum {
    SPR_YORO        = 0,
    SPR_FILES       = 1,
    SPR_FOLDER      = 2,
    SPR_TRASH_EMPTY = 3,
    SPR_TRASH_FULL  = 4,
    SPR_BROWSER     = 5,
    SPR_STORE       = 6,
    SPR_TERMINAL    = 7,
    SPR_SETTINGS    = 8,
    SPR_INSTALLER   = 9,
    SPR_EXE         = 10,
    SPR_TXT         = 11,
    SPR_ZIP         = 12,
    SPR_MATRONIX    = 13,
    SPR_CHROME      = 14,
    SPR_FIREFOX     = 15,
    SPR_STEAM       = 16,
    SPR_PYTHON      = 17,
    SPR_VSCODE      = 18
};

u32 icon_id(const char *name) {
    if (!name) return ICON_APP;
    if (!strcasecmp(name, "folder") || !strcasecmp(name, "explorer")) return ICON_FOLDER;
    if (!strcasecmp(name, "terminal") || !strcasecmp(name, "cmd")) return ICON_TERMINAL;
    if (!strcasecmp(name, "settings")) return ICON_SETTINGS;
    if (!strcasecmp(name, "browser")) return ICON_BROWSER;
    if (!strcasecmp(name, "store")) return ICON_STORE;
    if (!strcasecmp(name, "steam")) return ICON_STEAM;
    if (!strcasecmp(name, "python")) return ICON_PYTHON;
    if (!strcasecmp(name, "vscode") || !strcasecmp(name, "code")) return ICON_VSCODE;
    if (!strcasecmp(name, "notepad")) return ICON_NOTEPAD;
    if (!strcasecmp(name, "calc")) return ICON_CALC;
    if (!strcasecmp(name, "computer") || !strcasecmp(name, "thispc")) return ICON_COMPUTER;
    if (!strcasecmp(name, "trash")) return ICON_TRASH;
    if (!strcasecmp(name, "matronix")) return ICON_MATRONIX;
    if (!strcasecmp(name, "chrome")) return ICON_CHROME;
    if (!strcasecmp(name, "firefox")) return ICON_FIREFOX;
    if (!strcasecmp(name, "git")) return ICON_GIT;
    if (!strcasecmp(name, "vlc")) return ICON_VLC;
    if (!strcasecmp(name, "discord")) return ICON_DISCORD;
    if (!strcasecmp(name, "paint")) return ICON_PAINT;
    if (!strcasecmp(name, "setup") || !strcasecmp(name, "installer")) return ICON_SETUP;
    if (!strcasecmp(name, "zip")) return ICON_ZIP;
    if (!strcasecmp(name, "exe")) return ICON_EXE;
    if (!strcasecmp(name, "taskmgr")) return ICON_TASKMGR;
    if (!strcasecmp(name, "regedit")) return ICON_REGEDIT;
    return ICON_APP;
}

void avatar_draw(int avatar_id, int x, int y, int s) {
    static const Color bg[6] = {
        {59, 130, 246, 255}, {16, 185, 129, 255}, {124, 58, 237, 255},
        {217, 119, 6, 255},  {14, 165, 233, 255}, {71, 85, 105, 255}
    };
    int cx = x + s / 2, cy = y + s / 2;
    fill_circle(cx, cy, s / 2, bg[avatar_id % 6]);
    fill_circle(cx, cy - s / 8, s / 5, C_WHITE);
    fill_round_rect((Rect){cx - s * 28 / 100, cy + s / 9, s * 56 / 100, s * 26 / 100}, s / 8, C_WHITE);
}

/* Bilinear alpha-blended sprite draw for crystal-clear icons at ANY pixel size! */
static void blit_bgra_sprite(const u32 *src, int sw, int x, int y, int dst_sz) {
    int dx, dy;
    if (dst_sz <= 0) return;

    if (dst_sz == sw) {
        for (dy = 0; dy < sw; dy++) {
            for (dx = 0; dx < sw; dx++) {
                u32 p = src[dy * sw + dx];
                u8 a = (u8)(p >> 24);
                if (a == 0) continue;
                blend_px(x + dx, y + dy, RGB((p >> 16) & 0xFFU, (p >> 8) & 0xFFU, p & 0xFFU), a);
            }
        }
        return;
    }

    for (dy = 0; dy < dst_sz; dy++) {
        int fy = (dy * (sw - 1) * 256) / (dst_sz > 1 ? (dst_sz - 1) : 1);
        int sy = fy >> 8, wy = fy & 255;
        int sy1 = sy + 1 < sw ? sy + 1 : sy;
        for (dx = 0; dx < dst_sz; dx++) {
            int fx = (dx * (sw - 1) * 256) / (dst_sz > 1 ? (dst_sz - 1) : 1);
            int sx = fx >> 8, wx = fx & 255;
            int sx1 = sx + 1 < sw ? sx + 1 : sx;
            u32 p00 = src[sy * sw + sx],   p10 = src[sy * sw + sx1];
            u32 p01 = src[sy1 * sw + sx],  p11 = src[sy1 * sw + sx1];
            u32 w00 = (u32)(256 - wx) * (u32)(256 - wy);
            u32 w10 = (u32)wx         * (u32)(256 - wy);
            u32 w01 = (u32)(256 - wx) * (u32)wy;
            u32 w11 = (u32)wx         * (u32)wy;
            u8 a = (u8)((((p00 >> 24) & 255U) * w00 + ((p10 >> 24) & 255U) * w10 +
                         ((p01 >> 24) & 255U) * w01 + ((p11 >> 24) & 255U) * w11) >> 16);
            if (a < 4) continue;
            {
                u8 r = (u8)((((p00 >> 16) & 255U) * w00 + ((p10 >> 16) & 255U) * w10 +
                             ((p01 >> 16) & 255U) * w01 + ((p11 >> 16) & 255U) * w11) >> 16);
                u8 g = (u8)((((p00 >> 8) & 255U) * w00 + ((p10 >> 8) & 255U) * w10 +
                             ((p01 >> 8) & 255U) * w01 + ((p11 >> 8) & 255U) * w11) >> 16);
                u8 b = (u8)(((p00 & 255U) * w00 + (p10 & 255U) * w10 +
                             (p01 & 255U) * w01 + (p11 & 255U) * w11) >> 16);
                blend_px(x + dx, y + dy, RGB(r, g, b), a);
            }
        }
    }
}

static void draw_sprite(int spr_id, int x, int y, int s) {
    if (s <= 30)
        blit_bgra_sprite(g_icon28_bgra[spr_id], 28, x, y, s);
    else
        blit_bgra_sprite(g_icon48_bgra[spr_id], 48, x, y, s);
}

void icon_draw(u32 id, int x, int y, int s) {
    int m = s >= 24 ? s / 8 : 2;
    Rect box = {x + m, y + m, s - m * 2, s - m * 2};
    int cx = x + s / 2, cy = y + s / 2;
    int rad = s >= 32 ? 8 : 5;

    switch (id) {
    case ICON_COMPUTER:
    case ICON_DRIVE:        draw_sprite(SPR_FILES, x, y, s); break;
    case ICON_FOLDER:       draw_sprite(SPR_FOLDER, x, y, s); break;
    case ICON_TRASH_EMPTY:  draw_sprite(SPR_TRASH_EMPTY, x, y, s); break;
    case ICON_TRASH:        draw_sprite(SPR_TRASH_FULL, x, y, s); break;
    case ICON_BROWSER:      draw_sprite(SPR_BROWSER, x, y, s); break;
    case ICON_STORE:        draw_sprite(SPR_STORE, x, y, s); break;
    case ICON_TERMINAL:     draw_sprite(SPR_TERMINAL, x, y, s); break;
    case ICON_SETTINGS:     draw_sprite(SPR_SETTINGS, x, y, s); break;
    case ICON_SETUP:
    case ICON_RESTORE:      draw_sprite(SPR_INSTALLER, x, y, s); break;
    case ICON_EXE:
    case ICON_APP:          draw_sprite(SPR_EXE, x, y, s); break;
    case ICON_NOTEPAD:
    case ICON_TEXTFILE:
    case ICON_CODEFILE:     draw_sprite(SPR_TXT, x, y, s); break;
    case ICON_ZIP:          draw_sprite(SPR_ZIP, x, y, s); break;
    case ICON_MATRONIX:     draw_sprite(SPR_MATRONIX, x, y, s); break;
    case ICON_CHROME:       draw_sprite(SPR_CHROME, x, y, s); break;
    case ICON_FIREFOX:      draw_sprite(SPR_FIREFOX, x, y, s); break;
    case ICON_STEAM:        draw_sprite(SPR_STEAM, x, y, s); break;
    case ICON_PYTHON:      draw_sprite(SPR_PYTHON, x, y, s); break;
    case ICON_VSCODE:       draw_sprite(SPR_VSCODE, x, y, s); break;
    case ICON_ABOUT:
    case ICON_SHIELD:       draw_sprite(SPR_YORO, x, y, s); break;

    case ICON_CALC: {
        int r2, c2;
        fill_round_rect(box, rad, RGB(51, 65, 85));
        fill_round_rect((Rect){box.x + 4, box.y + 4, box.w - 8, s / 4}, 3, RGB(226, 232, 240));
        for (r2 = 0; r2 < 2; r2++)
            for (c2 = 0; c2 < 3; c2++)
                fill_round_rect((Rect){box.x + 4 + c2 * ((box.w - 6) / 3),
                                       box.y + s / 3 + 3 + r2 * (s / 5),
                                       (box.w - 12) / 3, s / 6}, 2,
                                (r2 == 1 && c2 == 2) ? RGB(56, 189, 248) : RGB(100, 116, 139));
        break;
    }
    case ICON_IMAGE:
    case ICON_PAINT: {
        fill_round_rect(box, rad, RGB(37, 99, 235));
        fill_circle(x + s * 66 / 100, y + s * 34 / 100, s / 9 + 1, RGB(250, 204, 21));
        {
            int xs[3] = {box.x + 3, cx, box.x + box.w - 3};
            int ys[3] = {box.y + box.h - 3, cy, box.y + box.h - 3};
            fill_poly(xs, ys, 3, RGB(52, 211, 153));
        }
        break;
    }
    case ICON_GIT: {
        fill_round_rect(box, rad, RGB(234, 88, 12));
        draw_line(cx - s / 6, cy + s / 7, cx + s / 6, cy - s / 7, C_WHITE);
        fill_circle(cx - s / 6, cy + s / 7, 3, C_WHITE);
        fill_circle(cx + s / 6, cy - s / 7, 3, C_WHITE);
        break;
    }
    case ICON_VLC: {
        fill_round_rect(box, rad, RGB(249, 115, 22));
        {
            int xs[3] = {cx - s / 7, cx - s / 7, cx + s / 5};
            int ys[3] = {cy - s / 5, cy + s / 5, cy};
            fill_poly(xs, ys, 3, C_WHITE);
        }
        break;
    }
    case ICON_DISCORD: {
        fill_round_rect(box, rad, RGB(99, 102, 241));
        fill_round_rect((Rect){x + s / 4, y + s / 3, s / 2, s / 3}, 5, C_WHITE);
        fill_circle(cx - s / 10, cy, 2, RGB(99, 102, 241));
        fill_circle(cx + s / 10, cy, 2, RGB(99, 102, 241));
        break;
    }
    case ICON_TASKMGR: {
        fill_round_rect(box, rad, RGB(30, 41, 59));
        draw_line(box.x + 4, cy + 3, cx - 3, cy + 3, RGB(52, 211, 153));
        draw_line(cx - 3, cy + 3, cx, box.y + 6, RGB(52, 211, 153));
        draw_line(cx, box.y + 6, cx + 4, box.y + box.h - 6, RGB(52, 211, 153));
        draw_line(cx + 4, box.y + box.h - 6, box.x + box.w - 4, cy, RGB(52, 211, 153));
        break;
    }
    case ICON_REGEDIT: {
        fill_round_rect(box, rad, RGB(51, 65, 85));
        hline(box.x + 5, box.x + box.w - 5, cy - 4, RGB(56, 189, 248));
        hline(box.x + 5, box.x + box.w - 5, cy + 4, C_WHITE);
        fill_circle(cx - 4, cy - 4, 3, C_WHITE);
        fill_circle(cx + 4, cy + 4, 3, RGB(56, 189, 248));
        break;
    }
    case ICON_POWER: {
        fill_circle(cx, cy, s / 3, RGBA(239, 68, 68, 46));
        draw_round_rect((Rect){cx - s / 4, cy - s / 4 + 2, s / 2, s / 2}, s / 4, RGB(248, 113, 113));
        vline(cx, y + s / 5, cy, C_WHITE);
        break;
    }
    case ICON_SEARCH: {
        fill_circle(cx - 2, cy - 2, s / 4, RGBA(255, 255, 255, 200));
        fill_circle(cx - 2, cy - 2, s / 4 - 2, theme->task_bg);
        draw_line(cx + 2, cy + 2, x + s - m - 2, y + s - m - 2, RGBA(255, 255, 255, 210));
        break;
    }
    case ICON_WIFI: {
        int r2;
        for (r2 = 1; r2 <= 3; r2++)
            hline(cx - r2 * (s / 8), cx + r2 * (s / 8), y + s * 3 / 4 - r2 * (s / 7), C_WHITE);
        fill_circle(cx, y + s * 3 / 4, 2, C_WHITE);
        break;
    }
    case ICON_VOLUME: {
        fill_rect((Rect){x + s / 4, cy - 3, 4, 6}, C_WHITE);
        draw_line(x + s / 4 + 4, cy - 3, cx, y + s / 4, C_WHITE);
        draw_line(x + s / 4 + 4, cy + 3, cx, y + s * 3 / 4, C_WHITE);
        vline(cx, y + s / 4, y + s * 3 / 4, C_WHITE);
        vline(cx + 4, cy - 4, cy + 4, RGB(148, 163, 184));
        break;
    }
    case ICON_BELL: {
        fill_round_rect((Rect){cx - s / 5, y + s / 4, s * 2 / 5, s * 2 / 5}, 4, C_WHITE);
        hline(cx - s / 4, cx + s / 4, y + s * 2 / 3, C_WHITE);
        fill_circle(cx, y + s * 3 / 4, 2, C_WHITE);
        break;
    }
    case ICON_UP:
        draw_line(cx, y + s / 4, cx - s / 5, cy, theme->text_main);
        draw_line(cx, y + s / 4, cx + s / 5, cy, theme->text_main);
        vline(cx, y + s / 4, y + s * 3 / 4, theme->text_main);
        break;
    case ICON_BACK:
        draw_line(x + s / 4, cy, cx, cy - s / 5, theme->text_main);
        draw_line(x + s / 4, cy, cx, cy + s / 5, theme->text_main);
        hline(x + s / 4, x + s * 3 / 4, cy, theme->text_main);
        break;
    case ICON_PLUS:
        hline(x + s / 4, x + s * 3 / 4, cy, theme->text_main);
        vline(cx, y + s / 4, y + s * 3 / 4, theme->text_main);
        break;
    case ICON_DOWNLOAD:
    case ICON_ARROW_DOWN:
        vline(cx, y + s / 5, y + s * 7 / 10, RGB(56, 189, 248));
        draw_line(cx - s / 5, cy, cx, y + s * 7 / 10, RGB(56, 189, 248));
        draw_line(cx + s / 5, cy, cx, y + s * 7 / 10, RGB(56, 189, 248));
        hline(x + s / 4, x + s * 3 / 4, y + s * 4 / 5, RGB(56, 189, 248));
        break;
    case ICON_CHECK: {
        fill_circle(cx, cy, s * 40 / 100, RGB(16, 185, 129));
        draw_line(cx - s / 5, cy, cx - 2, cy + s / 6, C_WHITE);
        draw_line(cx - 2, cy + s / 6, cx + s / 4, cy - s / 6, C_WHITE);
        draw_line(cx - s / 5, cy + 1, cx - 2, cy + s / 6 + 1, C_WHITE);
        draw_line(cx - 2, cy + s / 6 + 1, cx + s / 4, cy - s / 6 + 1, C_WHITE);
        break;
    }
    default:
        draw_sprite(SPR_YORO, x, y, s);
        break;
    }
}
